// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/catalogo/lista", wrapper.ListaVigente)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/catalogo/categorias", wrapper.Categorias)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/catalogo/marcas", wrapper.Marcas)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/catalogo/rubros", wrapper.Rubros)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/catalogo/productos", wrapper.Productos)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/catalogo/productos/pagina", wrapper.PaginaDeProductos)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/catalogo/productos/{slug}", wrapper.Producto)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/catalogo/productos/{id}/sugeridos", wrapper.Sugeridos)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/catalogo/precios-por-variante", wrapper.PreciosPorVariante)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/catalogo/complementos", wrapper.Complementos)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/catalogo/numeros", wrapper.Numeros)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/catalogo/portada", wrapper.Portada)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/catalogo/mi-lista", wrapper.MiLista)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/asistente/entender", wrapper.EntenderAsistente)

	return m
}

